"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"
import { Scrollbar, type ScrollbarSection } from "@/components/ui/scrollbar"

type ScrollAreaProps = React.ComponentProps<"div"> & {
  /** Marks on the rail, one per section inside: pointing at the rail brings their numbers down it, and pressing one scrolls there. */
  sections?: ScrollbarSection[]
  /** ruled: a rule at an edge while there's more beyond it. catchword: the first word below the edge waits on the foot rule. wheel: the rows turn on an arc as it scrolls. */
  variant?: "ruled" | "catchword" | "wheel"
}

/** The first word whose line runs under the foot line (the edge), and where it stands, or null at the end. */
function wordBelow(box: HTMLElement, foot: HTMLElement) {
  if (box.scrollTop + box.clientHeight >= box.scrollHeight - 1) return null
  const edge = foot.getBoundingClientRect().top + 0.5
  const skip = (n: Node) => (n.parentElement?.closest("[aria-hidden=true]") ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT)
  const walk = document.createTreeWalker(box, NodeFilter.SHOW_TEXT, { acceptNode: skip })
  const range = document.createRange()
  for (let n = walk.nextNode() as Text | null; n; n = walk.nextNode() as Text | null) {
    range.selectNodeContents(n)
    const all = range.getBoundingClientRect()
    if (!all.height || all.bottom <= edge) continue // wholly in view, or above it
    for (const m of n.data.matchAll(/\S+/g)) {
      range.setStart(n, m.index)
      range.setEnd(n, m.index + m[0].length)
      const r = range.getBoundingClientRect()
      if (r.bottom > edge) return { word: m[0], top: r.top }
    }
  }
  return null
}

/**
 * The catchword, after the printer's: the first word of the next page set at the foot of this one. While there's more
 * below, the first word cut off by the foot waits on the rule at the far end; pressing it turns the box to that line.
 */
function useCatchword(box: React.RefObject<HTMLDivElement | null>, on: boolean) {
  React.useEffect(() => {
    const host = box.current
    const word = host?.querySelector<HTMLElement>("[data-slot=scroll-catchword]")
    const foot = word?.parentElement
    if (!on || !host || !word || !foot) return
    let frame = 0, top = 0
    const read = () => {
      const hit = wordBelow(host, foot)
      word.toggleAttribute("data-idle", !hit)
      if (!hit || hit.word === word.textContent) return
      top = hit.top
      word.textContent = hit.word
      word.removeAttribute("data-turn") // the new word turns in (the tempo token collapses it for reduced motion)
      void word.offsetWidth
      word.setAttribute("data-turn", "")
    }
    const soon = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(read)
    }
    const turn = (e: PointerEvent) => {
      if (e.button) return
      e.preventDefault() // keep focus where it is
      const hit = wordBelow(host, foot)
      if (hit) top = hit.top
      const y = host.scrollTop + top - (host.getBoundingClientRect().top + host.clientTop) - 8
      host.scrollTo({ top: y, behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth" })
    }
    const resize = new ResizeObserver(soon)
    const mutation = new MutationObserver(soon)
    resize.observe(host)
    mutation.observe(host, { childList: true, subtree: true, characterData: true })
    host.addEventListener("scroll", soon, { passive: true })
    word.addEventListener("pointerdown", turn)
    document.fonts.ready.then(soon)
    read()
    return () => {
      cancelAnimationFrame(frame)
      resize.disconnect()
      mutation.disconnect()
      host.removeEventListener("scroll", soon)
      word.removeEventListener("pointerdown", turn)
    }
  }, [box, on])
}

/**
 * A box that scrolls. A rule appears at an edge only while there's more beyond it, and the
 * scrollbar is the page's own ruler rail: down the side, and along the bottom when the content runs sideways
 * (each rail stays hidden until there's something to scroll its way). Give it a height (or max-height) and a
 * name: it takes focus so the keyboard can scroll it, and a name says what it holds.
 * variant="catchword" sets the first word waiting below on the foot rule; variant="wheel" turns the children of
 * what you put inside on an arc, the one in the middle in ink.
 */
function ScrollArea({ className, children, sections, variant = "ruled", ref: forwardedRef, ...props }: ScrollAreaProps) {
  const named = props["aria-label"] || props["aria-labelledby"]
  const box = React.useRef<HTMLDivElement>(null)
  const composedRef = useComposedRefs(box, forwardedRef)
  useCatchword(box, variant === "catchword")
  return (
    <div ref={composedRef} data-slot="scroll-area" data-variant={variant} tabIndex={0} role={named ? "region" : undefined} className={cn("ot-scroll", className)} {...props}>
      {children}
      {variant === "catchword" && (
        <div className="ot-scroll-foot" aria-hidden="true">
          <span data-slot="scroll-catchword" data-idle="" className="ot-scroll-catchword" />
        </div>
      )}
      <Scrollbar sections={sections} />
      <Scrollbar axis="x" sections={sections} />
    </div>
  )
}

export { ScrollArea }

@layer components {
  /* ── ot-scroll ── a rule appears at an edge only while there's more beyond it */
  .ot-scroll {
    overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--ot-rule-strong) transparent;
    /* The paper covering each rule scrolls with the content; the rules stay put. */
    background:
      linear-gradient(var(--ot-paper), var(--ot-paper)) 0 0 / 100% 2px no-repeat local,
      linear-gradient(var(--ot-paper), var(--ot-paper)) 0 100% / 100% 2px no-repeat local,
      linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) 0 0 / 100% var(--ot-hairline) no-repeat scroll,
      linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) 0 100% / 100% var(--ot-hairline) no-repeat scroll;
  }
  /* The scroll area wears the page's rail: as wide, its hairline as far in, with a mark at each of its sections.
     It holds two rails (down and along), so it is positioned itself rather than have each rail ask for it. */
  .ot-scroll[data-slot="scroll-area"] { position: relative; }
  .ot-scroll[data-slot="scroll-area"] > .ot-scrollbar { --line: 0.5rem; width: 1.5rem; }
  .ot-scroll[data-slot="scroll-area"] > .ot-scrollbar[data-axis="x"] { width: auto; height: 1.5rem; }

  /* Catchword, after the printer's: the first word of the next page set alone on a line at the foot of this one, so the
     reader goes on. While there's more below, a foot line of paper rides the bottom of the box (sticky, with no script) and
     the text passes under it; on it, at the far end and clear of the rail, waits the first word the foot cuts off, over
     the rule. Each new word turns in as it arrives. Pressing it turns the box to that line. At the end the word and the rule go. */
  .ot-scroll-foot {
    position: sticky; bottom: 0; z-index: 2; display: flex; justify-content: flex-end; align-items: end; height: 1.625rem; padding-inline-end: 1.75rem;
    background: var(--ot-paper); pointer-events: none;
    border-block-end: var(--ot-hairline) solid var(--ot-rule-strong); /* the rule, drawn on the foot so it sits over what passes under */
  }
  .ot-scroll-foot:has(> [data-idle]) { border-block-end-color: transparent; }
  .ot-scroll-catchword {
    padding-block-end: 0.2rem; font-size: var(--ot-pp); line-height: var(--ot-pp-lh); letter-spacing: var(--ot-pp-tr); color: var(--ot-pencil);
    white-space: nowrap; cursor: pointer; pointer-events: auto; transition: color var(--ot-allegro) var(--ot-exhale);
  }
  .ot-scroll-catchword:hover { color: var(--ot-ink); }
  .ot-scroll-catchword[data-idle] { visibility: hidden; }
  .ot-scroll-catchword[data-turn] { animation: ot-scroll-turn var(--ot-allegro) var(--ot-exhale); }
  @keyframes ot-scroll-turn { from { opacity: 0; translate: 0 0.6em; } }

  /* Wheel, after WOVE, where numbers ride an arc, shrinking and fading by their distance from the chosen one: the children
     of what you put inside turn on an arc as the box scrolls. The row in the middle stands at the start edge, full size, in
     ink; rows toward the top and bottom fall back along the curve toward the rail, a little smaller, and step back to pencil.
     Each row runs on its own view timeline, so the wheel keeps time with the scroll and nothing moves while it rests.
     With reduced motion only the ink changes. */
  .ot-scroll[data-variant="wheel"] { --ot-scroll-arc: var(--ot-space-7); overflow-x: hidden; padding-inline-end: var(--ot-scroll-arc); }
  .ot-scroll[data-variant="wheel"] > :first-child > * { transform-origin: left center; }
  :is([dir="rtl"], [dir="rtl"] *).ot-scroll[data-variant="wheel"] { --ot-scroll-dir: -1; }
  :is([dir="rtl"], [dir="rtl"] *).ot-scroll[data-variant="wheel"] > :first-child > * { transform-origin: right center; }
  @supports (animation-timeline: view()) {
    .ot-scroll[data-variant="wheel"] > :first-child > * { animation: ot-scroll-wheel linear both; animation-timeline: view(); }
    @media (prefers-reduced-motion: reduce) { .ot-scroll[data-variant="wheel"] > :first-child > * { animation-name: ot-scroll-wheel-still; } }
  }
  /* Offset by the square of the distance d from the middle (d = 1, 0.8, 0.6, 0.4, 0.2, 0), so the curve reads across a short box. */
  @keyframes ot-scroll-wheel {
    0%, 100% { translate: calc(var(--ot-scroll-arc) * var(--ot-scroll-dir, 1)) 0; scale: 0.84; color: var(--ot-rule-strong); }
    10%, 90% { translate: calc(0.64 * var(--ot-scroll-arc) * var(--ot-scroll-dir, 1)) 0; scale: 0.9; }
    20%, 80% { translate: calc(0.36 * var(--ot-scroll-arc) * var(--ot-scroll-dir, 1)) 0; scale: 0.94; color: var(--ot-pencil); }
    30%, 70% { translate: calc(0.16 * var(--ot-scroll-arc) * var(--ot-scroll-dir, 1)) 0; scale: 0.97; color: var(--ot-graphite); }
    40%, 60% { translate: calc(0.04 * var(--ot-scroll-arc) * var(--ot-scroll-dir, 1)) 0; scale: 0.99; }
    50% { translate: 0 0; scale: 1; color: var(--ot-ink); }
  }
  @keyframes ot-scroll-wheel-still {
    0%, 100% { color: var(--ot-rule-strong); }
    20%, 80% { color: var(--ot-pencil); }
    30%, 70% { color: var(--ot-graphite); }
    50% { color: var(--ot-ink); }
  }
}
